"use client"

import type { Stage } from "@/lib/contracts"
import { STAGES, STAGE_INDEX } from "@/lib/stages"
import { cn } from "@/lib/utils"

/**
 * Where the case has got to.
 *
 * The same five colours as the event dock, in the same order as the sections
 * below. A viewer learns the vocabulary once.
 */
export function StageRail({ stage }: { stage: Stage }) {
  const reached = STAGE_INDEX[stage] ?? 0
  return (
    <ol className="flex items-center gap-1.5">
      {STAGES.map((entry, index) => {
        const done = index <= reached
        return (
          <li key={entry.id} className="flex items-center gap-1.5">
            <span
              className={cn(
                "flex items-center gap-1.5 rounded-pill px-2.5 py-1 text-[11px] font-semibold uppercase tracking-[0.88px] transition-colors",
                done ? entry.pill : "bg-hairline-soft text-muted-soft",
              )}
            >
              {entry.label}
            </span>
            {index < STAGES.length - 1 ? (
              <span
                className={cn("h-px w-3", index < reached ? "bg-hairline-strong" : "bg-hairline")}
              />
            ) : null}
          </li>
        )
      })}
    </ol>
  )
}

import { backendBaseUrl, startDevinSession } from "@/lib/cases/devin"
import { corsHeaders, json } from "@/lib/cases/http"
import { incidentFixture, incidentProblem } from "@/lib/cases/incidents"
import { appendEvent, createCase, setSession } from "@/lib/cases/store"
import type { Incident } from "@/lib/cases/types"
import { shortfall } from "@/lib/cases/types"

export async function OPTIONS(request: Request): Promise<Response> {
  return new Response(null, { status: 204, headers: corsHeaders(request) })
}

export async function POST(request: Request): Promise<Response> {
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return json({ error: "body must be JSON" }, 400, request)
  }

  const { case_id: caseId, incident: given } = (body ?? {}) as {
    case_id?: unknown
    incident?: unknown
  }
  if (typeof caseId !== "string" || caseId === "") {
    return json({ error: "case_id is required" }, 400, request)
  }

  let incident: Incident
  if (given === undefined) {
    const fixture = incidentFixture(caseId)
    if (!fixture) {
      return json({ error: `no incident fixture for ${caseId}` }, 404, request)
    }
    incident = fixture
  } else {
    const problem = incidentProblem(given)
    if (problem) return json({ error: problem }, 400, request)
    incident = given as Incident
    if (incident.case_id !== caseId) {
      return json({ error: "incident.case_id must match case_id" }, 400, request)
    }
  }

  createCase(incident)
  appendEvent(caseId, {
    actor: "system",
    stage: "created",
    message: `Case ${caseId} created for part ${incident.part_id}: short ${shortfall(incident)} of ${incident.qty_required}, line stops ${incident.line_stop_at}`,
    payload: { incident, shortfall: shortfall(incident) },
  })

  const baseUrl = backendBaseUrl(request.url)
  const session = await startDevinSession(incident, baseUrl)
  setSession(caseId, session.session_id, session.session_url)
  appendEvent(caseId, {
    actor: "system",
    stage: "session_started",
    level: session.error ? "warn" : "info",
    message: session.stubbed
      ? `Stub Devin session ${session.session_id}${session.error ? ` (${session.error})` : " (DEVIN_API_KEY not set)"}`
      : `Devin session ${session.session_id} started`,
    payload: {
      session_id: session.session_id,
      session_url: session.session_url,
      stubbed: session.stubbed,
      backend_base_url: baseUrl,
    },
  })

  return json(
    {
      case_id: caseId,
      session_id: session.session_id,
      session_url: session.session_url,
      stubbed: session.stubbed,
    },
    201,
    request
  )
}

/**
 * Devin session launcher.
 *
 * Real path: POST {DEVIN_API_BASE_URL}/v1/sessions with a bearer token
 * (https://docs.devin.ai/api-reference/v1/sessions/create-a-new-devin-session).
 * Without DEVIN_API_KEY we return a stub session so Slice 1 never fails on a
 * missing key. The key is only ever read from the environment.
 */

import type { Incident } from "./types"
import { shortfall } from "./types"

const DEFAULT_API_BASE_URL = "https://api.devin.ai"

export type DevinSession = {
  session_id: string
  session_url: string
  stubbed: boolean
  /** Set when the real API was attempted and failed; we still return a stub. */
  error?: string
}

export function backendBaseUrl(requestUrl: string): string {
  const configured = process.env.DEVIN_BACKEND_BASE_URL
  if (configured) return configured.replace(/\/$/, "")
  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`
  return new URL(requestUrl).origin
}

export function sessionPrompt(incident: Incident, baseUrl: string): string {
  return [
    `You are launching sourcing case ${incident.case_id}. Do not wait for a human — there is nobody to ask.`,
    `Backend base URL: ${baseUrl}. Read the case with GET ${baseUrl}/api/cases/${incident.case_id}/events.`,
    `Part ${incident.part_id} is short by ${shortfall(incident)} units (required ${incident.qty_required}, on hand ${incident.qty_on_hand}).`,
    `The line stops at ${incident.line_stop_at}. Costs are ${incident.currency} ${incident.line_stop_cost_per_hour}/hour of line stop and ${incident.expedite_fee} expedite fee.`,
    `Call only this backend. Do not place phone calls and do not contact suppliers in this slice.`,
  ].join("\n")
}

function stubSession(incident: Incident, error?: string): DevinSession {
  const suffix = incident.case_id.toLowerCase().replace(/[^a-z0-9]+/g, "-")
  const sessionId = `devin-stub-${suffix}-${Date.now()}`
  return {
    session_id: sessionId,
    session_url: `https://app.devin.ai/sessions/${sessionId}`,
    stubbed: true,
    error,
  }
}

export async function startDevinSession(
  incident: Incident,
  baseUrl: string
): Promise<DevinSession> {
  const apiKey = process.env.DEVIN_API_KEY
  if (!apiKey) return stubSession(incident)

  const apiBase = (
    process.env.DEVIN_API_BASE_URL ?? DEFAULT_API_BASE_URL
  ).replace(/\/$/, "")

  try {
    const response = await fetch(`${apiBase}/v1/sessions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        prompt: sessionPrompt(incident, baseUrl),
        title: `Sourcing ${incident.case_id} (${incident.part_id})`,
        tags: ["supplyguard", incident.case_id],
      }),
    })
    if (!response.ok) {
      const body = await response.text()
      return stubSession(
        incident,
        `Devin API ${response.status}: ${body.slice(0, 200)}`
      )
    }
    const data = (await response.json()) as {
      session_id?: string
      url?: string
    }
    if (!data.session_id) {
      return stubSession(incident, "Devin API response had no session_id")
    }
    return {
      session_id: data.session_id,
      session_url:
        data.url ?? `https://app.devin.ai/sessions/${data.session_id}`,
      stubbed: false,
    }
  } catch (error) {
    return stubSession(incident, `Devin API request failed: ${String(error)}`)
  }
}

/** Slice 1 domain types: Incident in, Event out. Money is always a string. */

export type Incident = {
  case_id: string
  part_id: string
  part_description?: string
  qty_required: number
  qty_on_hand: number
  line_stop_at: string
  /** Decimal string, never a float. */
  line_stop_cost_per_hour: string
  /** Decimal string, never a float. */
  expedite_fee: string
  currency: string
}

export type EventLevel = "info" | "warn" | "error"

export type CaseEvent = {
  case_id: string
  ts: string
  actor: string
  stage: string
  level: EventLevel
  message: string
  payload: Record<string, unknown>
}

export type CaseRecord = {
  case_id: string
  incident: Incident
  created_at: string
  session_id: string | null
  session_url: string | null
}

export function shortfall(incident: Incident): number {
  return Math.max(incident.qty_required - incident.qty_on_hand, 0)
}

"use client"

import * as React from "react"

import { getEvents } from "@/lib/api/client"
import type { Event } from "@/lib/contracts"

/**
 * The event feed.
 *
 * Two modes over one code path. `poll` asks the API for everything after the
 * last sequence number it saw, every two seconds -- which on stage looks
 * identical to a websocket and costs a tenth as much. `replay` takes the
 * recorded log and re-emits it with its original pacing compressed by `speed`,
 * so the cockpit tells the whole story with the backend switched off.
 *
 * Both end up calling the same `setEvents`, so the offline demo is not a second
 * implementation that can drift from the live one.
 */
export function useEvents(
  caseId: string,
  options: { replay?: boolean; speed?: number; enabled?: boolean } = {},
) {
  const { replay = false, speed = 4, enabled = true } = options
  const [events, setEvents] = React.useState<Event[]>([])
  const [complete, setComplete] = React.useState(false)

  React.useEffect(() => {
    if (!enabled) {
      setEvents([])
      setComplete(false)
      return
    }

    let cancelled = false
    const timers: ReturnType<typeof setTimeout>[] = []

    async function start() {
      const all = await getEvents(caseId)
      if (cancelled) return

      if (!replay) {
        setEvents(all)
        setComplete(true)
        let since = all.length ? (all[all.length - 1].seq ?? 0) : 0
        const tick = async () => {
          if (cancelled) return
          const fresh = await getEvents(caseId, since)
          if (cancelled) return
          if (fresh.length) {
            since = fresh[fresh.length - 1].seq ?? since
            setEvents((prior) => [...prior, ...fresh])
          }
          timers.push(setTimeout(tick, 2000))
        }
        timers.push(setTimeout(tick, 2000))
        return
      }

      if (!all.length) {
        setComplete(true)
        return
      }
      const origin = new Date(all[0].ts).getTime()
      all.forEach((event, index) => {
        const offset = (new Date(event.ts).getTime() - origin) / speed
        timers.push(
          setTimeout(() => {
            if (cancelled) return
            setEvents((prior) => [...prior, event])
            if (index === all.length - 1) setComplete(true)
          }, offset),
        )
      })
    }

    start()
    return () => {
      cancelled = true
      timers.forEach(clearTimeout)
    }
  }, [caseId, replay, speed, enabled])

  return { events, complete }
}

/**
 * Seeded Incident fixtures.
